create table RB_BUS_APPR_LETTER (INCOME_SCOPE VARCHAR(50) null  ,NARRATIVE VARCHAR(600) null  ,APPR_ACCT_IND VARCHAR(2) null  ,OPEN_DATE TIMESTAMP(3) not null  ,FUND_SOURCE VARCHAR(1) null  ,EXPEND_SCOPE VARCHAR(200) null  ,RB_ACCT_TYPE VARCHAR(1) null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,APPR_TYPE VARCHAR(2) null  ,APPR_LETTER_NO VARCHAR(50) not null  ,FUND_PURPOSE VARCHAR(50) null  ,CAPITAL_AMT DECIMAL(17,2) null  ,TRAN_BRANCH VARCHAR(30) not null  ,CLIENT_NO VARCHAR(22) not null  ,MATURITY_DATE TIMESTAMP(3) not null  ,CREATE_TIMESTAMP VARCHAR(26) not null  , primary key(APPR_LETTER_NO,CLIENT_NO));